import{_ as a,o as t,c as l,a5 as i}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"Vue.js中，filter（过滤器）","description":"在Vue.js中，filter（过滤器）用于对文本格式化，它们是用来格式化文本输出的实用工具。过滤器可以在双花括号插值和v bind表达式（必须带有管道符“ ”）中使用。 理解Vue的过滤器 1. 定义过滤器 ： 过滤器可以在Vue实例中全局定义，也可以在组件中局部定义。 2.。","frontmatter":{"title":"Vue.js中，filter（过滤器）","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在Vue.js中，filter（过滤器）用于对文本格式化，它们是用来格式化文本输出的实用工具。过滤器可以在双花括号插值和v bind表达式（必须带有管道符“ ”）中使用。 理解Vue的过滤器 1. 定义过滤器 ： 过滤器可以在Vue实例中全局定义，也可以在组件中局部定义。 2.。","sidebarWeight":17,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/Vue.js中，filter（过滤器）.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/Vue.js中，filter（过滤器）.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/Vue.js中，filter（过滤器）.md"}'),r={name:"posts/Vue系统教程/02-模板、组件与交互/Vue.js中，filter（过滤器）.md"};function o(u,e,s,n,d,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<div><h1 id="vue-js中-filter-过滤器" tabindex="-1">Vue.js中，filter（过滤器） <a class="header-anchor" href="#vue-js中-filter-过滤器" aria-label="Permalink to &quot;Vue.js中，filter（过滤器）&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue.js中，filter（过滤器）”的核心思路，并能把它用于实际开发或面试表达。 在Vue.js中，filter（过滤器）用于对文本格式化，它们是用来格式化文本输出的实用工具。过滤器可以在双花括号插值和v-bind表达式（必须带有管道符“|”）中使用。</p></blockquote><h3 id="理解vue的过滤器" tabindex="-1">理解Vue的过滤器 <a class="header-anchor" href="#理解vue的过滤器" aria-label="Permalink to &quot;理解Vue的过滤器&quot;">​</a></h3><ol><li><strong>定义过滤器</strong>：</li></ol><ul><li>过滤器可以在Vue实例中全局定义，也可以在组件中局部定义。</li></ul><ol start="2"><li><strong>使用过滤器</strong>：</li></ol><ul><li>过滤器通常与数据绑定在一起使用，以对显示的数据进行格式化处理。</li></ul><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h3><h4 id="全局过滤器" tabindex="-1">全局过滤器 <a class="header-anchor" href="#全局过滤器" aria-label="Permalink to &quot;全局过滤器&quot;">​</a></h4><p>要注册一个全局过滤器，可以使用<code>Vue.filter</code>方法： Vue.filter(&#39;capitalize&#39;, function (value) { if (!value) return &#39;&#39; value = value.toString() return value.charAt(0).toUpperCase() + value.slice(1) })</p><h4 id="局部过滤器" tabindex="-1">局部过滤器 <a class="header-anchor" href="#局部过滤器" aria-label="Permalink to &quot;局部过滤器&quot;">​</a></h4><p>在组件中局部定义过滤器： new Vue({ el: &#39;#app&#39;, data: { message: &#39;hello world&#39; }, filters: { capitalize: function (value) { if (!value) return &#39;&#39; value = value.toString() return value.charAt(0).toUpperCase() + value.slice(1) } } })</p><h4 id="在模板中使用过滤器" tabindex="-1">在模板中使用过滤器 <a class="header-anchor" href="#在模板中使用过滤器" aria-label="Permalink to &quot;在模板中使用过滤器&quot;">​</a></h4><p>使用管道符<code>|</code>来调用过滤器： &lt;span&gt;{{ message | capitalize }}&lt;/span&gt;</p><h4 id="在v-bind中使用过滤器" tabindex="-1">在<code>v-bind</code>中使用过滤器 <a class="header-anchor" href="#在v-bind中使用过滤器" aria-label="Permalink to &quot;在`v-bind`中使用过滤器&quot;">​</a></h4><p>&lt;div v-bind:id=&quot;rawId | formatId&quot;&gt;&lt;/div&gt;</p><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>假设我们有一个时间戳，我们想要格式化它，使其更具可读性：</p><ol><li>定义过滤器： Vue.filter(&#39;formatDate&#39;, function (value) { if (!value) return &#39;&#39; let date = new Date(value) return date.toLocaleDateString() + &#39; &#39; + date.toLocaleTimeString() })</li><li>使用过滤器： &lt;div&gt;{{ timestamp | formatDate }}&lt;/div&gt; 这样，<code>timestamp</code>的值将会被格式化为一个本地化的日期和时间字符串。</li></ol><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>Vue的过滤器是一种简洁的方法，用于格式化数据，使其在模板中显示时更加友好。通过全局或局部定义过滤器，可以很方便地在多个组件中重用这些格式化逻辑。</p></div>',1)])])}const p=a(r,[["render",o]]);export{f as __pageData,p as default};
